import { Schema, defineFormula } from '@qualy/formula'

export default defineFormula({
  input: Schema.input({
    score: Schema.decimal({ minimum: '0.00', maximum: '100.00', maxScale: 2 }),
    weight: Schema.integer({ minimum: 1, maximum: 10 }),
    tier: Schema.choice({ national: '国家级', provincial: '省级' }),
    verified: Schema.boolean(),
    awardedOn: Schema.date(),
    title: Schema.text({ maxLength: 120, pattern: '^[A-Za-z0-9 ]+$' }),
  }),
  output: Schema.scoreAmount({ maxScale: 4 }),
  run: (input, q) => {
    const base = q.decimal.mulInteger(input.score, input.weight)
    if (!input.verified) q.fail('unverified evidence')
    return q.decimal.quantize(base, 4)
  },
})
